using System;
using System.IO;
using System.IO.Compression;
using Microsoft.Build.Logging.StructuredLogger;

// The binlog v25 uses zstd compression. Let's try to decompress manually first.
// Actually, let's use the MSBuild SDK's own replay functionality
var readerSettings = new ReaderSettings { AllowForwardCompatibility = true };
try {
    var build = BinaryLog.ReadBuild("build.binlog", readerSettings: readerSettings);
    Console.WriteLine("Success!");
} catch (Exception ex) {
    Console.WriteLine($"Failed: {ex.Message}");

    // Try reading with the raw reader
    Console.WriteLine("\nTrying raw reader...");
    var reader = new BinLogReader();
    reader.OnBuildError += (sender, args) => {
        Console.WriteLine($"ERROR: {args?.Fields?.Message}");
    };
}
