import re

with open('build.binlog', 'rb') as f:
    data = f.read()

# Extract all text segments >= 3 chars
text_segments = re.findall(b'[\x20-\x7e]{3,}', data)
all_text = [seg.decode('ascii') for seg in text_segments]

# Look for various error indicators
print("=== MSB errors ===")
for s in all_text:
    if 'MSB' in s and ('error' in s.lower() or 'failed' in s.lower()):
        print(f"  {s[:300]}")
        print()

print("\n=== Source files referenced ===")
source_files = set()
for s in all_text:
    if s.endswith('.cs') or s.endswith('.csproj') or '.cs(' in s:
        source_files.add(s[:200])
for f in sorted(source_files)[:30]:
    print(f"  {f}")

print("\n=== 'Build FAILED' context ===")
# Find "Build FAILED" and get surrounding text
for i, s in enumerate(all_text):
    if 'Build FAILED' in s:
        # Show surrounding segments
        start = max(0, i-10)
        end = min(len(all_text), i+10)
        for j in range(start, end):
            print(f"  [{j}] {all_text[j][:200]}")
        break

print("\n=== Warning/error counts ===")
for s in all_text:
    if 'Warning(s)' in s or 'Error(s)' in s:
        print(f"  {s}")
